# -*- coding: utf-8 -*-
"""Science Stage 7 · Unit 4 Classifying Living Things – Read the lesson (shown below the video) and the lesson document (PDF).
Camday's own text, examples and questions; scope: Cambridge Lower Secondary Science 0893, Stage 7 (7Bp.01–7Bp.04, 7SIC.01, 7TWSc.01)."""
from maths_notes_v4.kit4 import H, I, Y, X, K, L, BK, Ex, mcq, grid, num

READ = {}
CARD = lambda title, cards, cols=None: dict({"kind": "sciCards", "title": title, "cards": cards}, **({"cols": cols} if cols else {}))


def KEY(nodes, edges, w=104):
    """a branching key drawn with the flow figure: nodes = [(x, y, text, colour?)], edges = [(a, b, 'yes'/'no')]"""
    return {"kind": "flow", "nodes": [dict(x=n[0], y=n[1], t=n[2], **({"c": n[3]} if len(n) > 3 else {})) for n in nodes], "edges": [list(e) for e in edges], "w": w}


# =====================================================================================================
# 4.1 Characteristics of living things · 7Bp.01
# =====================================================================================================
READ["4.1"] = L(
    H("Alive or not?",
      "A candle flame grows, moves, 'feeds' on wax and gives off waste gases. A seed in a packet does nothing at all for months.",
      "Which one is alive? Decide, and keep your answer – you will check it at the end of this lesson."),
    I("Biodiversity and classification",
      "The Earth holds millions of kinds of living things. A country with a huge variety of living things, such as Brazil or Indonesia, has a rich **biodiversity**.",
      then=["To study so many organisms, scientists sort them into groups – **classification**. It also helps us to find and protect endangered species, such as the orangutan."]),
    I("Seven life processes: MRS GREN",
      "All living things (**organisms**) are made of cells and carry out **seven life processes**. Remember them with **MRS GREN**.",
      table=[["Letter", "Life process", "What it means", "Example"],
             ["M", "**movement**", "changing position, all or part of the body", "a gecko runs up a wall; a sunflower turns to the Sun"],
             ["R", "**respiration**", "chemical reactions in cells that release energy from food", "your muscle cells respire as you run"],
             ["S", "**sensitivity**", "sensing changes around them and responding", "a cat's pupils narrow in bright light"],
             ["G", "**growth**", "getting bigger: more cells, or bigger cells", "a caterpillar grows before it becomes a butterfly"],
             ["R", "**reproduction**", "making new organisms of the same kind", "a hen lays eggs; a strawberry plant sends out runners"],
             ["E", "**excretion**", "getting rid of waste made inside the body", "you breathe out carbon dioxide; leaves release oxygen"],
             ["N", "**nutrition**", "taking in or making food", "plants make food by photosynthesis; a heron eats fish"]],
      then=["A living thing does **all seven**. Non-living things may show one or two (a car moves, a crystal grows), but never all seven."]),
    I("Nutrition: plants and animals",
      "**Plants and algae** make their own food by **photosynthesis**, using light energy, carbon dioxide and water.",
      then=["**Animals** cannot make their own food. They eat plants, other animals, or both. **Fungi** such as mushrooms feed on dead material."]),
    I("Predict, watch, explain: is yeast alive?",
      "Yeast is a fungus. Two bottles are kept at 35 °C for an hour, each with a balloon on top.",
      table=[["Bottle", "Contents", "After 1 hour"], ["A", "yeast + warm water + sugar", "frothy; balloon blown up"], ["B", "yeast + warm water, no sugar", "balloon hardly changed"]],
      then=["In bottle A the yeast used sugar as food (**nutrition**) and **respired**, releasing **carbon dioxide** gas that filled the balloon. In B the yeast had no food.",
            "So yeast shows life processes – it is alive. Bottle B is the **control**: it shows that the sugar made the difference."]),
    Y("Which life process?",
      grid("s7u04r11", "Which life process does each example show?", ["Sensitivity", "Excretion", "Reproduction", "Growth"],
           [("A snail pulls back into its shell when touched.", "Sensitivity"), ("You sweat and breathe out carbon dioxide.", "Excretion"),
            ("A mango tree produces seeds.", "Reproduction"), ("A puppy gets bigger each month.", "Growth")],
           "Think MRS GREN.", "Responding to touch = sensitivity; removing waste = excretion; seeds = reproduction; getting bigger = growth.")),
    I("Back to the candle and the seed",
      "A candle flame shows some features of life, but it is not made of cells, it does not reproduce and it does not respire in cells. It is **not alive**.",
      then=["The seed is alive but **dormant** (resting). Given water and warmth, it respires, grows and later reproduces."]),
    X("Plants move too",
      "Many students say plants do not move.",
      "Plants cannot move from place to place, but **parts** of them move slowly: shoots grow towards light, climbing stems wind round a stick, and some leaves fold up at night."),
    K("Key points",
      "**Biodiversity** is the variety of living things; classification sorts them into groups.",
      "All living things carry out **MRS GREN**: movement, respiration, sensitivity, growth, reproduction, excretion, nutrition.",
      "Plants make food by photosynthesis; animals must eat.",
      "Yeast released carbon dioxide when it had sugar: it respires, so it is alive."),
    book=BK(
        [("organism", "a living thing"), ("biodiversity", "the variety of living things in an area"), ("respiration", "chemical reactions in cells that release energy from food"),
         ("sensitivity", "sensing and responding to changes in the surroundings"), ("excretion", "getting rid of waste made in the body"), ("nutrition", "taking in or making food")],
        [], [],
        [Ex("Write out what each letter of MRS GREN stands for.", ans="movement, respiration, sensitivity, growth, reproduction, excretion, nutrition"),
         Ex("Name the life process:", ("a bean shoot grows towards a window", "sensitivity (and movement)"), ("a fish takes in oxygen and releases energy from food", "respiration"),
            ("a rabbit eats grass", "nutrition")),
         Ex("A robot can move, sense light and 'feed' on electricity. Explain why it is not a living thing.", ans="It is not made of cells and it cannot grow, reproduce, respire or excrete."),
         Ex("In the yeast experiment, why was bottle B set up with no sugar?", ans="As a control – to show that the gas was produced only when the yeast had food.", think=True),
         Ex("Leila says that plants do not excrete. Is she right? Explain.", ans="No – plants get rid of waste gases such as oxygen (from photosynthesis) and carbon dioxide (from respiration).", think=True)],
        ["explain what biodiversity and classification are", "name and describe the seven life processes", "decide whether something is living using MRS GREN"],
        look=["the MRS GREN table", "the yeast and sugar experiment"],
        note="Read it after the video: MRS GREN, nutrition, the yeast experiment and the practice on paper (answers at the back)."),
)

