# 4.2 Viruses · 7Bp.02
# =====================================================================================================
READ["4.2"] = L(
    H("A cold in a sneeze",
      "One sneeze sends thousands of tiny droplets into the air. A few days later, the person next to you has a cold.",
      "What travelled in those droplets, and is it alive? Write your answer, then test it in this lesson."),
    I("What is a virus?",
      "A **virus** is much smaller than a bacterium – most are about 0.0001 mm across, so you need an electron microscope to see one.",
      fig=CARD("A virus particle", [{"t": "Genetic material", "d": "DNA or RNA – the instructions to make more viruses"}, {"t": "Protein coat", "d": "protects the genetic material"},
                                    {"t": "Envelope (some viruses)", "d": "an extra outer layer"}, {"t": "No cell", "d": "no nucleus, cytoplasm or mitochondria"}], 4)),
    I("How a virus copies itself",
      "A virus can only make copies of itself **inside a living cell**, called a **host cell**.",
      fig={"kind": "sciFlow", "title": "A virus inside a host cell", "steps": [{"t": "Attaches", "d": "to a host cell"}, {"t": "Injects", "d": "its genetic material"},
                                                                              {"t": "Copies", "d": "the cell makes new viruses"}, {"t": "Bursts out", "d": "and infects more cells"}]},
      then=["Different viruses attack different hosts: animals, plants and even bacteria."]),
    I("Are viruses living or non-living?",
      "Scientists still discuss this question. Test viruses against MRS GREN:",
      table=[["Feature of living things", "Do viruses show it?"],
             ["made of cells", "**no** – a virus is not a cell"], ["respiration", "**no** – no mitochondria"], ["nutrition and excretion", "**no** – they do not feed or produce waste"],
             ["movement", "**no** – carried by air, water or body fluids"], ["contain genetic material", "**yes**"], ["reproduction", "**only inside a host cell**"]],
      then=["So a virus particle on its own is usually called **non-living**. Some scientists argue that inside a host cell, the virus and cell together act like a living thing."]),
    Y("Living or not?",
      mcq("s7u04r21", "Which is the best reason why viruses are usually described as non-living?",
          [("They are not made of cells and cannot respire.", True, "Yes – all living things are made of cells and respire."),
           ("They are too small to see.", False, "Bacteria are too small to see too, but they are alive."),
           ("They cause disease.", False, "Many living bacteria and fungi cause disease too."), ("They contain genetic material.", False, "That is a feature of living things.")],
          "Use the characteristics of living things.", "Viruses have no cells and do not respire, feed or excrete, so they fail most of the MRS GREN tests.")),
    I("Real life: viruses around us",
      "Viruses affect us every day.",
      table=[["Example", "What happens"],
             ["colds and flu", "viruses infect cells lining the nose, throat or lungs"], ["vaccines", "train the body to recognise a virus such as measles or polio before it can make us ill"],
             ["antibiotics", "kill bacteria but **do not work against viruses**"], ["plant viruses", "for example mosaic viruses cause patchy, yellow-green leaves on crops"]]),
    X("Antibiotics do not cure a cold",
      "Many people ask for antibiotics when they have a cold or flu.",
      "Colds and flu are caused by **viruses**. Antibiotics only kill **bacteria**, so they do not help – and taking them when they are not needed helps bacteria become resistant."),
    K("Key points",
      "A virus is genetic material in a protein coat; it is not a cell.",
      "Viruses copy themselves only inside a **host cell**, often destroying it.",
      "Viruses do not respire, feed, excrete or move by themselves, so they are usually called **non-living**.",
      "Vaccines protect against viruses; **antibiotics do not** work on viruses."),
    book=BK(
        [("virus", "a tiny particle of genetic material in a protein coat that reproduces only inside cells"), ("host cell", "a living cell that a virus invades"),
         ("vaccine", "trains the body to recognise a disease before you catch it"), ("antibiotic", "a medicine that kills bacteria")],
        [], [],
        [Ex("Describe the structure of a virus.", ans="Genetic material (DNA or RNA) inside a protein coat; some have an outer envelope. It has no cell parts."),
         Ex("Put these in order: new viruses burst out; virus attaches to the cell; cell makes copies of the virus; virus injects its genetic material.",
            ans="attaches; injects genetic material; cell makes copies; new viruses burst out"),
         Ex("Give two reasons for calling viruses non-living and one reason for calling them living.",
            ans="Non-living: not made of cells; do not respire / feed / excrete. Living: they have genetic material and reproduce inside host cells."),
         Ex("Explain why a doctor does not give antibiotics for the flu.", ans="Flu is caused by a virus and antibiotics only kill bacteria.", think=True)],
        ["describe the structure of a virus", "explain how a virus reproduces", "discuss whether viruses are living or non-living"],
        look=["the four steps of virus copying", "the living / non-living table"],
        note="Read it after the video: what viruses are, how they copy, the living or non-living debate (answers at the back)."),
)

