    I("A branching key: five pond animals",
      "Start at the top and answer each question about your animal.",
      fig=KEY([(240, 30, "Has legs?"), (130, 110, "6 legs?"), (360, 110, "Has a shell?"), (60, 200, "water beetle", "#DFF4EA"), (190, 200, "water mite", "#DFF4EA"),
               (300, 200, "pond snail", "#DFF4EA"), (400, 200, "Flat body?"), (340, 285, "flatworm", "#DFF4EA"), (432, 285, "leech", "#DFF4EA")],
              [(0, 1, "yes"), (0, 2, "no"), (1, 3, "yes"), (1, 4, "no"), (2, 5, "yes"), (2, 6, "no"), (6, 7, "yes"), (6, 8, "no")], w=88)),
